const ContactForm = () => {
    const [formData, setFormData] = useState({
        fullName: '',
        email: '',
        phone: ''
    });

    const [errors, setErrors] = useState({});
    const [submitted, setSubmitted] = useState(false);

    const validate = () => {
        const newErrors = {};

        // Full Name Validation
        if (!formData.fullName.trim()) {
            newErrors.fullName = 'Full name is required';
        }

        // Email Validation
        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (!formData.email.trim()) {
            newErrors.email = 'Email address is required';
        } else if (!emailRegex.test(formData.email)) {
            newErrors.email = 'Please enter a valid email address';
        }

        // Phone Validation (Optional)
        if (formData.phone.trim()) {
            const phoneRegex = /^\(?([0-9]{3})\)?[-. ]?([0-9]{3})[-. ]?([0-9]{4})$/;
            if (!phoneRegex.test(formData.phone)) {
                newErrors.phone = 'Please enter a valid phone number (e.g., (555) 555-5555)';
            }
        }

        setErrors(newErrors);
        return Object.keys(newErrors).length === 0;
    };

    const handleChange = (e) => {
        const { name, value } = e.target;
        setFormData(prev => ({
            ...prev,
            [name]: value
        }));

        // Clear error when user starts typing
        if (errors[name]) {
            setErrors(prev => ({
                ...prev,
                [name]: ''
            }));
        }
    };

    const handleSubmit = (e) => {
        e.preventDefault();
        if (validate()) {
            console.log('Form Submitted:', formData);
            setSubmitted(true);
            // In a real app, you'd send this to an API
        }
    };

    if (submitted) {
        return (
            <div className="container">
                <div className="success-message">
                    <h2>Thank you!</h2>
                    <p>Your support request has been submitted successfully. We'll get back to you soon.</p>
                </div>
                <button 
                    className="mt-4" 
                    onClick={() => {
                        setSubmitted(false);
                        setFormData({ fullName: '', email: '', phone: '' });
                    }}
                    style={{
                        marginTop: '1rem',
                        backgroundColor: '#f3f4f6',
                        color: '#374151',
                        border: '1px solid #d1d5db',
                        padding: '0.5rem',
                        borderRadius: '0.375rem',
                        width: '100%',
                        cursor: 'pointer'
                    }}
                >
                    Send another message
                </button>
            </div>
        );
    }

    return (
        <div className="container">
            <h1>Contact Support</h1>
            <p className="subtitle">Fill out the form below and we'll be in touch.</p>

            <form onSubmit={handleSubmit} noValidate>
                <div className="form-field">
                    <label htmlFor="fullName">Full Name</label>
                    <input
                        type="text"
                        id="fullName"
                        name="fullName"
                        value={formData.fullName}
                        onChange={handleChange}
                        className={errors.fullName ? 'error' : ''}
                        placeholder="Jane Doe"
                        required
                    />
                    {errors.fullName && <span className="error-message">{errors.fullName}</span>}
                </div>

                <div className="form-field">
                    <label htmlFor="email">Email Address</label>
                    <input
                        type="email"
                        id="email"
                        name="email"
                        value={formData.email}
                        onChange={handleChange}
                        className={errors.email ? 'error' : ''}
                        placeholder="jane@example.com"
                        required
                    />
                    {errors.email && <span className="error-message">{errors.email}</span>}
                </div>

                <div className="form-field">
                    <label htmlFor="phone">Phone Number (Optional)</label>
                    <input
                        type="tel"
                        id="phone"
                        name="phone"
                        value={formData.phone}
                        onChange={handleChange}
                        className={errors.phone ? 'error' : ''}
                        placeholder="(555) 555-5555"
                    />
                    <span className="helper-text">Expected format: (555) 555-5555</span>
                    {errors.phone && <span className="error-message">{errors.phone}</span>}
                </div>

                <button type="submit">Submit Request</button>
            </form>
        </div>
    );
};

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<ContactForm />);
